var i=`1207-yuca-frita-con-chicharron`;var t=`world-1207`;var n=`SV`;var r=`central-america-caribbean`;var o=4;var s=58;var l={en:`Yuca Frita con Chicharrón`,ua:`Смажена юка зі шкварками`};var c={en:`Yuca Frita con Chicharrón is a dish from El Salvador featuring cassava root, pork belly, garlic, white cabbage. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Смажена юка зі шкварками, страва кухні країни Сальвадор з такими основними складниками: маніок, свиняча грудинка, часник, білоголова капуста. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var d=[{en:`Cook the listed ingredients in simmering water for about 26 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 26 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:26,i:[[`cassava-root`,950,`g`],[`water`,1600,`ml`],[`table-salt`,10,`g`]]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 14 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 14 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:14,i:[[`canola-oil`,800,`ml`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 12 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 12 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:12,i:[[`pork-belly`,380,`g`],[`garlic`,3,`clove`]]},{en:`Arrange the fully cooked and prepared parts of the dish on plates or in the intended serving vessel, adding the listed toppings or accompaniments just before serving.`,ua:`Зберіть повністю приготовані частини страви на тарілках або в посуді для подавання, додавши зазначені топінги та доповнення безпосередньо перед подаванням.`,t:[`layered-assembly`,`garnishing`],m:6,i:[[`white-cabbage`,220,`g`],[`carrot`,140,`g`],[`white-vinegar`,90,`ml`]]}];var g={slug:i,id:t,country:`SV`,region:r,servings:4,minutes:58,title:l,text:c,steps:d};export{n as country,g as default,t as id,s as minutes,r as region,o as servings,i as slug,d as steps,c as text,l as title};